import os
import shutil


class Directories:
    """Class to organize file system operation like: create/remove directories."""

    def __init__(self, base_name, base_dir="."):
        """
        :param string base_name: Name is used to generate directory name.
        :param string base_dir:  Directory path where new directory will be created.
        """
        self._base_name = base_name
        self._base_dir = base_dir
        self.dir_path = None
        self.subdir_path = None
        self.backup_dir = None

    def create_dir(self, dir_name=None):
        """Create new directory.

        :param string  dir_name: Directory name that should be created. In case of `None`,
            library will generate new directory name based on `base_name`.
        """
        if not dir_name:
            dir_name = self._base_name
        dir_path = os.path.join(self._base_dir, dir_name)
        self._create_empty_dir(dir_path)

    def create_sub_dir(self, subdir):
        """Create subdirectory inside directory created by "create_dir" method.

        :param string subdir: Name of subdirectory that should be created.
        """
        if self.dir_path:
            subdir_path = os.path.join(self.dir_path, subdir)
            os.mkdir(subdir_path)
            self.subdir_path = subdir_path
        else:
            raise RuntimeError("Please first create base directory.")

    def move_to_created_dir(self, source):
        """Move specify source into main directory created by "create_dir" method.

        :param string source: File or directory to move.
        """
        self._move_to_dir(source, self.dir_path)

    def move_to_created_sub_dir(self, source):
        """Move specify source into subdirectory create by "create_sub_dir" method.

        :param string source: File or directory to move.
        """
        self._move_to_dir(source, self.subdir_path)

    def clean_dir(self):
        """Remove content from main directory."""
        if self.dir_path:
            shutil.rmtree(self.dir_path)
            os.mkdir(self.dir_path)

    def clean_sub_dir(self):
        """Remove content from subdirectory."""
        if self.subdir_path:
            shutil.rmtree(self.subdir_path)
            os.mkdir(self.subdir_path)

    def remove_dir(self):
        """Remove main directory created by "create_dir" method."""
        if self.dir_path:
            if os.path.exists(self.dir_path):
                shutil.rmtree(self.dir_path)

    def _create_empty_dir(self, dir_path):
        try:
            self._create_dir(dir_path)
        except OSError:
            shutil.rmtree(dir_path)
            self._create_dir(dir_path)

    def _create_dir(self, dir_path):
        os.mkdir(dir_path)
        self.dir_path = dir_path

    def _move_to_dir(self, source, dst):
        if os.path.exists(source):
            for each in os.listdir(source):
                shutil.move(os.path.join(source, each), dst)
